1. Tokenizing, Formatting, and Reversing Strings​ Strings can be broken apart into an array of tokens via split() or processed backward to reverse character order: package text_processing; public class StringOperations { public static void main(String[] args) { String phrase = "I love Java"; // Count words by splitting on whitespace countWords(phrase); // Reverse character sequence reverseString("stop"); } public static void countWords(String text) { // Split using a whitespace delimiter into an array of strings String[] words = text.split(" "); int numberOfWords = words.length; // Use format with %d digit placeholder String message = String.format("Your text contains %d words", numberOfWords); System.out.println(message); // Traverse the resulting string array for (int i = 0; i < words.length; i++) { System.out.println(words[i]); } } public static void reverseString(String text) { // Loop backward from last index (length - 1) down to 0 for (int i = text.length() - 1; i >= 0; i--) { // print instead of println keeps output on the same line System.out.print(text.charAt(i)); } System.out.println(); // Terminal line break } } 2. Multiline Formatting: Concatenation vs. Text Blocks​ Text blocks remove boilerplate escape characters for formatted payloads: package text_processing; public class TextBlockComparison { public static void main(String[] args) { // Traditional approach: requires explicit escape quotes ("), newlines (
), and concatenation String legacyJson = "{
" + " "language": "Java",
" + " "version": 17
" + "}"; // Modern approach: multiline text block with three double quotes // Opening delimiter must be followed immediately by a newline String modernJson = """ { "language": "Java", "version": 17 } """; System.out.println(legacyJson.equals(modernJson)); // Compares character content: true } }
